        if let Some(ConsentSource::Reference(ref mut r)) = self.0.source.as_mut() {
            refs.push(Box::new(r));
        }
        for policy in self.0.policy.iter_mut() {
            if let Some(policy) = policy.as_mut() {
                refs.extend(policy.lookup_references());
            }
        }
        for verification in self.0.verification.iter_mut() {
            if let Some(verification) = verification.as_mut() {
                refs.extend(verification.lookup_references());
            }
        }
        if let Some(provision) = self.0.provision.as_mut() {
            refs.extend(provision.lookup_references());
        }
        refs
