impl LookupReferences for Contract {
    fn lookup_references(&mut self) -> Vec<Box<&mut dyn ReferenceField>> {
        let mut refs: Vec<Box<&mut dyn ReferenceField>> = Vec::new();
        if let Some(instantiates_canonical) = self.0.instantiates_canonical.as_mut() {
            refs.push(Box::new(instantiates_canonical));
        }
        for subject in self.0.subject.iter_mut() {
            if let Some(subject) = subject.as_mut() {
                refs.push(Box::new(subject));
            }
        }
        for authority in self.0.authority.iter_mut() {
            if let Some(authority) = authority.as_mut() {
                refs.push(Box::new(authority));
            }
        }
        for domain in self.0.domain.iter_mut() {
            if let Some(domain) = domain.as_mut() {
                refs.push(Box::new(domain));
            }
        }
        for site in self.0.site.iter_mut() {
            if let Some(site) = site.as_mut() {
                refs.push(Box::new(site));
            }
        }
        if let Some(author) = self.0.author.as_mut() {
            refs.push(Box::new(author));
        }
        if let Some(ContractTopic::Reference(ref mut r)) = self.0.topic.as_mut() {
            refs.push(Box::new(r));
        }
        if let Some(content_definition) = self.0.content_definition.as_mut() {
            refs.extend(content_definition.lookup_references());
        }
        for term in self.0.term.iter_mut() {
            if let Some(term) = term.as_mut() {
                refs.extend(term.lookup_references());
            }
        }
        for supporting_info in self.0.supporting_info.iter_mut() {
            if let Some(supporting_info) = supporting_info.as_mut() {
                refs.push(Box::new(supporting_info));
            }
        }
        for relevant_history in self.0.relevant_history.iter_mut() {
            if let Some(relevant_history) = relevant_history.as_mut() {
                refs.push(Box::new(relevant_history));
            }
        }
        for signer in self.0.signer.iter_mut() {
            if let Some(signer) = signer.as_mut() {
                refs.extend(signer.lookup_references());
            }
        }
        for friendly in self.0.friendly.iter_mut() {
            if let Some(friendly) = friendly.as_mut() {
                refs.extend(friendly.lookup_references());
            }
        }
        for legal in self.0.legal.iter_mut() {
            if let Some(legal) = legal.as_mut() {
                refs.extend(legal.lookup_references());
            }
        }
        for rule in self.0.rule.iter_mut() {
            if let Some(rule) = rule.as_mut() {
                refs.extend(rule.lookup_references());
            }
        }
        if let Some(ContractLegallyBinding::Reference(ref mut r)) = self
            .0
            .legally_binding
            .as_mut()
        {
            refs.push(Box::new(r));
        }
        refs
    }
}
