impl LookupReferences for Observation {
    fn lookup_references(&mut self) -> Vec<Box<&mut dyn ReferenceField>> {
        let mut refs: Vec<Box<&mut dyn ReferenceField>> = Vec::new();
        for based_on in self.0.based_on.iter_mut() {
            if let Some(based_on) = based_on.as_mut() {
                refs.push(Box::new(based_on));
            }
        }
        for part_of in self.0.part_of.iter_mut() {
            if let Some(part_of) = part_of.as_mut() {
                refs.push(Box::new(part_of));
            }
        }
        if let Some(subject) = self.0.subject.as_mut() {
            refs.push(Box::new(subject));
        }
        for focus in self.0.focus.iter_mut() {
            if let Some(focus) = focus.as_mut() {
                refs.push(Box::new(focus));
            }
        }
        if let Some(encounter) = self.0.encounter.as_mut() {
            refs.push(Box::new(encounter));
        }
        for performer in self.0.performer.iter_mut() {
            if let Some(performer) = performer.as_mut() {
                refs.push(Box::new(performer));
            }
        }
        if let Some(specimen) = self.0.specimen.as_mut() {
            refs.push(Box::new(specimen));
        }
        if let Some(device) = self.0.device.as_mut() {
            refs.push(Box::new(device));
        }
        for reference_range in self.0.reference_range.iter_mut() {
            if let Some(reference_range) = reference_range.as_mut() {
                refs.extend(reference_range.lookup_references());
            }
        }
        for has_member in self.0.has_member.iter_mut() {
            if let Some(has_member) = has_member.as_mut() {
                refs.push(Box::new(has_member));
            }
        }
        for derived_from in self.0.derived_from.iter_mut() {
            if let Some(derived_from) = derived_from.as_mut() {
                refs.push(Box::new(derived_from));
            }
        }
        for component in self.0.component.iter_mut() {
            if let Some(component) = component.as_mut() {
                refs.extend(component.lookup_references());
            }
        }
        refs
    }
}
