impl LookupReferences for Specimen {
    fn lookup_references(&mut self) -> Vec<Box<&mut dyn ReferenceField>> {
        let mut refs: Vec<Box<&mut dyn ReferenceField>> = Vec::new();
        if let Some(subject) = self.0.subject.as_mut() {
            refs.push(Box::new(subject));
        }
        for parent in self.0.parent.iter_mut() {
            if let Some(parent) = parent.as_mut() {
                refs.push(Box::new(parent));
            }
        }
        for request in self.0.request.iter_mut() {
            if let Some(request) = request.as_mut() {
                refs.push(Box::new(request));
            }
        }
        if let Some(collection) = self.0.collection.as_mut() {
            refs.extend(collection.lookup_references());
        }
        for processing in self.0.processing.iter_mut() {
            if let Some(processing) = processing.as_mut() {
                refs.extend(processing.lookup_references());
            }
        }
        for container in self.0.container.iter_mut() {
            if let Some(container) = container.as_mut() {
                refs.extend(container.lookup_references());
            }
        }
        refs
    }
}
